#!/usr/bin/env Rscript
# ==============================================================================
# Transform 2023 Data to 2025 Schema Compliance
# ==============================================================================
#
# Purpose: Convert app/2023/ databases to match the schema documented in
#          app_DATAMODEL.md and app_DATA_DICTIONARY.md
#
# Input:  app/2023/*.rds (original 2023 format)
# Output: app/2023_compliance/*.rds (2025-compliant format)
#
# Author: Generated by Claude Code
# Date: 2026-03-07
# ==============================================================================

library(tidyverse)
library(dm)
library(glue)
library(fs)

# ==============================================================================
# Configuration
# ==============================================================================

INPUT_DIR <- "app/2023"
OUTPUT_DIR <- "app/2023_compliance"

# Create output directory
dir_create(OUTPUT_DIR, recurse = TRUE)

cat("\n")
cat("╔══════════════════════════════════════════════════════════════╗\n")
cat("║  2023 → 2025 Schema Compliance Transformation                ║\n")
cat("╚══════════════════════════════════════════════════════════════╝\n")
cat("\n")
cat("Input:  ", INPUT_DIR, "\n")
cat("Output: ", OUTPUT_DIR, "\n")
cat("\n")

# ==============================================================================
# 1. Transform ffa_db.rds
# ==============================================================================

cat("──────────────────────────────────────────────────────────────\n")
cat("📦 Processing ffa_db.rds\n")
cat("──────────────────────────────────────────────────────────────\n")

ffa_db_2023 <- readRDS(file.path(INPUT_DIR, "ffa_db.rds"))

# ──────────────────────────────────────────────────────────────────
# 1.1 Transform ffa_player_ids: Add missing columns
# ──────────────────────────────────────────────────────────────────

cat("  ⚙️  ffa_player_ids: Adding gsis_id and sleeper_id (as NA)\n")

ffa_player_ids_new <- ffa_db_2023$ffa_player_ids %>%
  mutate(
    gsis_id = NA_character_,      # Added in 2024+
    sleeper_id = NA_character_     # Added in 2024+
  ) %>%
  # Reorder to match 2025 schema
  select(
    id, stats_id, cbs_id, fleaflicker_id, nfl_id, espn_id,
    fftoday_id, numfire_id, fantasypro_id, fantasydata_id,
    fantasynerd_id, rts_id, fantasypro_num_id,
    gsis_id, sleeper_id  # New columns at end
  )

cat("     ✓ Added 2 columns (now ", ncol(ffa_player_ids_new), " cols)\n")

# ──────────────────────────────────────────────────────────────────
# 1.2 Transform ffa_projtable: Remove VOR, add player metadata
# ──────────────────────────────────────────────────────────────────

cat("  ⚙️  ffa_projtable: Removing VOR columns, adding player metadata\n")

ffa_projtable_new <- ffa_db_2023$ffa_projtable %>%
  # Remove VOR and uncertainty columns (2023 only)
  select(
    -points_vor, -floor_vor, -ceiling_vor,
    -floor_rank, -ceiling_rank,
    -pos_ecr, -sd_ecr, -uncertainty
  ) %>%
  # Add player metadata via join
  left_join(
    ffa_db_2023$ffa_players %>%
      select(id, pos, first_name, last_name, team, position, age, exp),
    by = c("id", "pos")
  ) %>%
  # Reorder columns to match 2025 schema
  select(
    season, week, tag, timestamp, avg_type, id, pos,
    points, sd_pts, dropoff, rank, tier, ceiling, floor,
    # Player metadata columns (new in 2025)
    first_name, last_name, team, position, age, exp,
    # Stats columns (if they exist in 2023)
    starts_with("pass_"),
    starts_with("rush_"),
    starts_with("rec_")
  )

cat("     ✓ Removed 8 VOR columns\n")
cat("     ✓ Added 6 player metadata columns\n")
cat("     ✓ Final columns: ", ncol(ffa_projtable_new), "\n")

# ──────────────────────────────────────────────────────────────────
# 1.3 Other ffa tables remain unchanged
# ──────────────────────────────────────────────────────────────────

ffa_players_new <- ffa_db_2023$ffa_players
ffa_proj_source_points_new <- ffa_db_2023$ffa_proj_source_points
ffa_scrape_new <- ffa_db_2023$ffa_scrape

cat("  ✓ ffa_players: No changes needed\n")
cat("  ✓ ffa_proj_source_points: No changes needed\n")
cat("  ✓ ffa_scrape: No changes needed\n")

# ──────────────────────────────────────────────────────────────────
# 1.4 Rebuild dm object
# ──────────────────────────────────────────────────────────────────

ffa_db_new <- dm(
  ffa_player_ids = ffa_player_ids_new,
  ffa_players = ffa_players_new,
  ffa_projtable = ffa_projtable_new,
  ffa_proj_source_points = ffa_proj_source_points_new,
  ffa_scrape = ffa_scrape_new
) %>%
  # Add primary keys
  dm_add_pk(ffa_player_ids, id) %>%
  dm_add_pk(ffa_players, c(id, pos)) %>%
  dm_add_pk(ffa_projtable, c(season, week, tag, timestamp, avg_type, id, pos)) %>%
  dm_add_pk(ffa_proj_source_points, c(season, week, tag, timestamp, data_src, id, pos)) %>%
  dm_add_pk(ffa_scrape, c(season, week, tag, timestamp)) %>%
  # Add foreign keys
  dm_add_fk(ffa_players, id, ffa_player_ids) %>%
  dm_add_fk(ffa_projtable, c(id, pos), ffa_players) %>%
  dm_add_fk(ffa_projtable, c(season, week, tag, timestamp), ffa_scrape) %>%
  dm_add_fk(ffa_proj_source_points, c(id, pos), ffa_players) %>%
  dm_add_fk(ffa_proj_source_points, c(season, week, tag, timestamp), ffa_scrape)

# Validate
dm_examine_constraints(ffa_db_new)

saveRDS(ffa_db_new, file.path(OUTPUT_DIR, "ffa_db.rds"))
cat("  💾 Saved: ", file.path(OUTPUT_DIR, "ffa_db.rds"), "\n\n")

# ==============================================================================
# 2. Transform nfl_players_db.rds
