cat("──────────────────────────────────────────────────────────────\n")
cat("📦 Processing nfl_players_db.rds\n")
cat("──────────────────────────────────────────────────────────────\n")

nfl_players_db_2023 <- readRDS(file.path(INPUT_DIR, "nfl_players_db.rds"))

# ──────────────────────────────────────────────────────────────────
