# ──────────────────────────────────────────────────────────────────

cat("  ⚙️  nfl_players: Adding lastNoteTimestamp column\n")

nfl_players_new <- nfl_players_db_2023$nfl_players %>%
  mutate(
    lastNoteTimestamp = NA_character_  # Added in 2024+
  ) %>%
  # Reorder to match 2025 schema (lastNoteTimestamp before lastVideoTimestamp)
  select(
    playerId, nflGlobalEntityId, esbId, name, firstName, lastName,
    position, nflTeamAbbr, nflTeamId, imageUrl, smallImageUrl,
    largeImageUrl, byeWeek, cancelledWeeks, archetypes,
    isUndroppable, isReserveStatus,
    lastNoteTimestamp,  # New column
    lastVideoTimestamp
  )

cat("     ✓ Added lastNoteTimestamp (now ", ncol(nfl_players_new), " cols)\n")

# ──────────────────────────────────────────────────────────────────
# 2.2 nfl_player_injury_status remains unchanged
# ──────────────────────────────────────────────────────────────────

nfl_player_injury_status_new <- nfl_players_db_2023$nfl_player_injury_status

cat("  ✓ nfl_player_injury_status: No changes needed\n")

# ──────────────────────────────────────────────────────────────────
# 2.3 Rebuild dm object
# ──────────────────────────────────────────────────────────────────

nfl_players_db_new <- dm(
  nfl_players = nfl_players_new,
  nfl_player_injury_status = nfl_player_injury_status_new
) %>%
  dm_add_pk(nfl_players, playerId) %>%
  dm_add_pk(nfl_player_injury_status, c(playerId, timestamp)) %>%
  dm_add_fk(nfl_player_injury_status, playerId, nfl_players)

dm_examine_constraints(nfl_players_db_new)

saveRDS(nfl_players_db_new, file.path(OUTPUT_DIR, "nfl_players_db.rds"))
cat("  💾 Saved: ", file.path(OUTPUT_DIR, "nfl_players_db.rds"), "\n\n")

# ==============================================================================
# 3. Transform nfl_stats_db.rds
# ==============================================================================

cat("──────────────────────────────────────────────────────────────\n")
cat("📦 Processing nfl_stats_db.rds\n")
cat("──────────────────────────────────────────────────────────────\n")

nfl_stats_db_2023 <- readRDS(file.path(INPUT_DIR, "nfl_stats_db.rds"))

cat("  ⚠️  WARNING: nfl_players_adv_stats has incompatible schema\n")
cat("     2023 columns: percentRostered, targets, redzoneTargets, etc.\n")
cat("     2025 columns: transactionBuysellAdd, leaguesOwned, etc.\n")
cat("     Action: Preserving original 2023 columns with compatibility note\n")

# ──────────────────────────────────────────────────────────────────
# 3.1 Add metadata to track incompatibility
# ──────────────────────────────────────────────────────────────────

nfl_players_adv_stats_new <- nfl_stats_db_2023$nfl_players_adv_stats %>%
  mutate(
    schema_version = "2023",
    schema_note = "INCOMPATIBLE: 2023 schema differs from 2025 (see CLAUDE.md)"
  )

cat("     ✓ Added schema_version and schema_note columns\n")

# ──────────────────────────────────────────────────────────────────
# 3.2 Other tables remain unchanged
# ──────────────────────────────────────────────────────────────────

nfl_stat_dictionary_new <- nfl_stats_db_2023$nfl_stat_dictionary
nfl_players_points_new <- nfl_stats_db_2023$nfl_players_points
nfl_players_stats_new <- nfl_stats_db_2023$nfl_players_stats

cat("  ✓ nfl_stat_dictionary: No changes needed\n")
cat("  ✓ nfl_players_points: No changes needed\n")
cat("  ✓ nfl_players_stats: No changes needed\n")

# ──────────────────────────────────────────────────────────────────
# 3.3 Rebuild dm object
# ──────────────────────────────────────────────────────────────────

nfl_stats_db_new <- dm(
  nfl_stat_dictionary = nfl_stat_dictionary_new,
  nfl_players_points = nfl_players_points_new,
  nfl_players_stats = nfl_players_stats_new,
  nfl_players_adv_stats = nfl_players_adv_stats_new
) %>%
  dm_add_pk(nfl_stat_dictionary, statId) %>%
  dm_add_pk(nfl_players_points, c(playerId, season, week)) %>%
  dm_add_pk(nfl_players_stats, c(playerId, season, week, statId)) %>%
  dm_add_pk(nfl_players_adv_stats, c(playerId, season, week)) %>%
  dm_add_fk(nfl_players_stats, statId, nfl_stat_dictionary)

dm_examine_constraints(nfl_stats_db_new)

saveRDS(nfl_stats_db_new, file.path(OUTPUT_DIR, "nfl_stats_db.rds"))
cat("  💾 Saved: ", file.path(OUTPUT_DIR, "nfl_stats_db.rds"), "\n\n")

