  "nfl_round_db.rds",
  "nfl_recap_db.rds",
  "dudes_simulation_db.rds"
)

for (file in files_to_compare) {
  orig_size <- file_size(file.path(INPUT_DIR, file))
  new_size <- file_size(file.path(OUTPUT_DIR, file))
  change <- new_size - orig_size
  change_pct <- (as.numeric(new_size) / as.numeric(orig_size) - 1) * 100

  report_lines <- c(
    report_lines,
    sprintf("| %s | %s | %s | %+.1f%% |",
            file,
            format(orig_size, units = "auto"),
            format(new_size, units = "auto"),
            change_pct)
  )
}

